CREATE TABLE IF NOT EXISTS gis_dataset_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES gis_authoritative_sources(id), dataset_name text NOT NULL, resource_type text NOT NULL, source_reference text NOT NULL, version_label text, received_at timestamptz NOT NULL DEFAULT now(), content_hash text, crs text, feature_count integer, provenance_status text NOT NULL DEFAULT 'UNVERIFIED', validation_status text NOT NULL DEFAULT 'PENDING', certification_status text NOT NULL DEFAULT 'PENDING', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_artifact_exception_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artifact_id uuid NOT NULL REFERENCES gis_dataset_artifacts(id) ON DELETE CASCADE, exception_id uuid NOT NULL, match_score numeric(5,2), evidence_type text, evidence_reference text, decision_status text NOT NULL DEFAULT 'PENDING', reviewer_id text, reviewed_at timestamptz, rationale text, created_at timestamptz NOT NULL DEFAULT now());